    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
else:
    t = ""

G = {}

for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h_str, w_str = m[1], m[2], m[3]
    h = int(h_str)
    w = int(w_str)
    # Get the grid data right after the header
    remaining = t[m.end():m.end()+h*500]  # approximate reading
    lines = remaining.split('\n')[:h]
    # Find the numeric grid rows
    grid_rows = []
    for line in lines:
        if line.strip() and ' ' in line:
            grid_rows.append(line.split())

    if k not in G and len(grid_rows) == h:
        G[k] = [[int(c) for c in row] for row in grid_rows]

print("Loaded grids:", list(G.keys()))

